"""Knowledge base for the Windows tools: error codes (Win32, HRESULT, NTSTATUS,
Kerberos, bug checks, Windows Update, Intune / Entra join) and HRESULT /
NTSTATUS facility names.

Only entries we are confident about are listed. Anything else is decoded
structurally by windiag.py and reported as "not in the knowledge base".
"""
from __future__ import annotations


def E(name, meaning, causes=(), fixes=(), cmds=(), related=(), sev=None, msg=None, notes=()):
    """One knowledge-base entry. `notes` are context-specific remarks
    (e.g. what the code means during Autopilot)."""
    return {"name": name, "meaning": meaning, "causes": list(causes), "fixes": list(fixes),
            "commands": list(cmds), "related": list(related), "severity": sev, "message": msg, "notes": list(notes)}


# Commands reused by several entries.
_DISM = "DISM /Online /Cleanup-Image /RestoreHealth"
_SFC = "sfc /scannow"
